# ===========================================================================
# fir_mac_loop.s - Q15 FIR filter using the custom MAC instructions
#
#   y[n] = sat16( (sum_{k=0}^{TAPS-1} h[k] * x[n-k]) >>> 15 ),  n = 0..N-1
#
# Data (fir_data.inc, generated by build.py):
#   x_pad : TAPS-1 zeros followed by the N input samples (Q15, .half)
#   h_rev : filter taps in reverse order, so both pointers walk forward:
#           y[n] = sum_j h_rev[j] * x_pad[n + j]
#   y     : N output samples (Q15, .half)
#
# Per tap the inner loop needs 7 instructions; the 'mac' accumulates into
# the unit's 64-bit accumulator, and 'rdacc.q15' does the Q30 -> Q15
# conversion with saturation in a single instruction.
# ===========================================================================
        .include "fir_data.inc"

        .text
start:
        la   s0, x_pad          # s0 -> x_pad[n]
        la   s1, h_rev
        la   s2, y
        li   s3, N
outer:
        mv   t0, s0
        mv   t1, s1
        li   t2, TAPS
        clracc
inner:
        lh   t3, 0(t0)          # x sample
        lh   t4, 0(t1)          # coefficient
        addi t0, t0, 2
        addi t1, t1, 2
        addi t2, t2, -1
        mac  x0, t3, t4         # ACC += x * h
        bnez t2, inner

        rdacc.q15 t5            # Q30 -> Q15 with saturation
        addi s0, s0, 2
        addi s3, s3, -1
        sh   t5, 0(s2)
        addi s2, s2, 2
        bnez s3, outer

        li   a0, 0x600D
        ecall
